INSERT INTO instructors (id, name, email, bio, avatar_url, specialty, years_experience, total_students, rating) VALUES
(1, 'Juan García López', 'juan@coderup.com', 'Experto en React y JavaScript moderno. 5 años en desarrollo frontend. Ha mentorizado a más de 2400 estudiantes. Apasionado por la arquitectura de componentes escalable, accesibilidad y rendimiento web.', '/instructors/juan-garcia.jpeg', 'React / Frontend', 5, 2400, 4.80),
(2, 'María López Rodríguez', 'maria@coderup.com', 'Especialista en backend con Node.js, PHP y bases de datos. 6 años en arquitectura de sistemas. Diseña APIs que sirven a millones de requests y acompaña a equipos en decisiones técnicas defendibles.', '/instructors/maria-lopez.png', 'Node.js / Backend', 6, 3100, 4.90),
(3, 'Carlos Rodríguez Pérez', 'carlos@coderup.com', 'DevOps engineer con experiencia en Docker, Kubernetes y AWS. 7 años en infraestructura. Ha desplegado sistemas críticos en producción y domina CI/CD, observabilidad y automatización.', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=400&h=400&q=82', 'DevOps / Infraestructura', 7, 1800, 4.70),
(4, 'Ana Martínez García', 'ana@coderup.com', 'Diseñadora UI/UX con pasión por la experiencia de usuario. 4 años en diseño digital. Ha trabajado con startups y grandes empresas, con foco en accesibilidad y sistemas visuales.', '/instructors/ana-martinez.png', 'Diseño UI/UX', 4, 900, 4.60);
